 August 2019}}</ref> | image = Hasima.jpg | lat = 32.75025555 | lon = 129.87780277 | type = 6 | id = 00003864 }} |- {{NHS Japan row | name ={{ill|Neso Kofun Cluster|en|Neso Kofun Cluster|qid=Q22119911|lt=Neso Kofun Cluster|1=Neso Kofun Cluster}} | name_kanji ={{nihongo2|[[:ja:根曽古墳群|根曽古墳群]]}} | name_small = Neso Kofun-gun | name_simple = Neso Kofun Cluster | municipality = {{ill|Tsushima, Nagasaki|en|Tsushima, Nagasaki|qid=Q991032|lt=Tsushima|1=Tsushima, Nagasaki}} | comments = Kofun period tumuli cluster | image =Neso Kofungun-1, funcho.jpg | lat =34.2618448 | lon =129.32391106 | type = 1 | id = 2773 }} |- {{NHS Japan row | name = {{ill|Dejima|en|Dejima|qid=Q640267|lt=Dejima Dutch Trading Post|1=Dejima}} | name_kanji = {{nihongo2|出島和蘭商館跡}} | name_small = Dejima Oranda shōkan ato | name_simple = Dejima Dutch Trading Post | municipality = {{ill|Nagasaki|en|Nagasaki|qid=Q38234|lt=Nagasaki|1=Nagasaki}} | comments = Edo Period Netherlands East India Company trading settlement | image = Nagasaki Dejima C1771.jpg | lat = 32.74347004 | lon = 129.87313698 | type = 9 | id = 2739 }} |- {{NHS Japan row | name ={{ill|Katsumoto Castle|en|Katsumoto Castle|qid=Q11400349|lt=Katsumoto Castle|1=Katsumoto Castle}} ruins | name_kanji ={{nihongo2|[[:ja:勝本城|勝本城]]跡}} | name_small = Katsumoto-jō ato | name_simple = Katsumoto Castle ruins | municipality = {{ill|Iki, Nagasaki|en|Iki, Nagasaki|qid=Q861519|lt=Iki|1=Iki, Nagasaki}} | comments = Sengoku period castle ruins | image = Site of Katsumoto Castle.jpg | lat = 33.84918217 | lon = 129.69100997 | type = 2 | id = 3334 }} |- {{NHS Japan row | name = {{ill|Kosuge Slip Dock|en|Kosuge Slip Dock|qid=Q734915|lt=Kosuge Slip Dock|1=Kosuge Slip Dock}} | name_kanji = 小菅修船場跡 | name_small = Kosuge shūsen-ba ato | name_simple = Kosuge Slip Dock | municipality = {{ill|Nagasaki|en|Nagasaki|qid=Q38234|lt=Nagasaki|1=Nagasaki}} | comments = Meiji period industrial site; inscribed on the [[:en:UNESCO World Heritage List|UNESCO World Heritage List]] as among t