a tenshudō keidai | name_simple = Ōura Church Precinct | municipality ={{ill|Nagasaki|en|Nagasaki|qid=Q38234|lt=Nagasaki|1=Nagasaki}} | comments = Bakumatsu period cathedral; National Treasure, inscribed on the [[:en:UNESCO World Heritage List|UNESCO World Heritage List]] as one of the {{ill|Hidden Christian Sites in the Nagasaki Region|en|Hidden Christian Sites in the Nagasaki Region|qid=Q93643|lt=Hidden Christian Sites in the Nagasaki Region|1=Hidden Christian Sites in the Nagasaki Region}}<ref name="UNESCO1"/> | image = Oura tenshudo 1.jpg | lat = 32.75025555 | lon =129.87780277 | type = 3, 9 | id = 3763 }} |- {{NHS Japan row | name = [[Ōmura Domain#Ōmura Domain Ōmura clan cemetery|Ōmura Domain Ōmura clan cemetery]] | name_kanji = 大村藩主大村家墓所 | name_small = Ōmura-han-shu Ōmura-ke bosho | name_simple = Ōmura Domain Ōmura clan cemetery | municipality = {{ill|Ōmura, Nagasaki|en|Ōmura, Nagasaki|qid=Q385591|lt=Ōmura|1=Ōmura, Nagasaki}} | comments = Edo Period daimyo cemetery | image = | lat = 32.91729611 | lon = 129.95426271 | type = 7 | id = 3408 }} |- {{NHS Japan row | name =[[Ōnodai Dolmen Cluster]] | name_kanji ={{nihongo2|大野台支石墓群}} | name_small =Ōnodai shisekibo-gun | name_simple = Ōnodai Dolmen Cluster | municipality =[[:en:Sasebo, Nagasaki|Sasebo]] | comments = Jōmon Period cemetery | image = Ohnodai shisekibogun.jpg | lat =33.29851005 | lon =129.61901207 | type = 1 | id = 2786 }} |- {{NHS Japan row | name = {{ill|Takashima Kōzaki Site|en|Takashima Kōzaki Site|qid=Q17226122|lt=Takashima Kōzaki Site|1=Takashima Kōzaki Site}} | name_kanji = 鷹島神崎遺跡 | name_small = Takashima Kōzaki iseki | name_simple = Takashima Kōzaki Site | municipality = {{ill|Matsuura, Nagasaki|en|Matsuura, Nagasaki|qid=Q850465|lt=Matsuura|1=Matsuura, Nagasaki}} | comments = Underwater site with traces from the Kamakura period Mongol Invasions of Japan | image = Kouzaki Underwater ruins.JPG | lat = 33.34119138 | lon = 129.70915 | type = 2 | id = 00003771 }} |- {{NHS Japan row | name =[[Atomic bombings of Hiroshima and Nagasaki#Nagasaki|Nagasaki Atomic Bomb Sites]] | name_kanji ={{nihongo2|[[:ja:長崎原爆遺跡|長崎原爆遺跡]]}} | name_small =Nagasaki genbaku iseki | name_simple = Nagasaki Atomic Bomb Sites | municipality ={{ill|Nagasaki|en|Nagasaki|qid=Q38234|lt=Nagasaki|1=Nagasaki}} | comments = Designation includes "Ground Zero", the former Shiroyama National School Building, old Bell Tower of Urakami Cathedral, gatepost of the Former Nagasaki Medical College & second torii gate of Sanno Shrine | image = Sanno-jinja-afterbomb.jpg | lat =32.75025555 | lon =129.87780277 | type = 2 | id = 00003956 }} |- {{NHS Japan row | name ={{ill|Nagasaki Battery sites|en|Nagasaki Battery sites|qid=Q128306246|lt=Nagasaki Battery sites|1=Nagasaki Battery sites}} | name_kanji ={{nihongo2|長崎台場跡}} | name_small =Nagasaki daiba ato | name_simple = Nagasaki Battery and Uomidake Battery sites | municipality ={{ill|Nagasaki|en|Nagasaki|qid=Q38234|lt=Nagasaki|1=Nagasaki}} | comments = Bakumatsu period fortifications; designation includes the sites of the {{nihongo|[[Uomidake Battery]]|魚見岳台場跡}} and {{nihongo|[[Shirōgashima Battery]]|四郎ヶ島台場跡}} | image = | lat =32.71792317 | lon =129.85240108 | type = 2 | id = 2787 }} |- {{NHS Japan row | name ={{ill|Tōnokubi Site|en|Tōnokubi Site|qid=Q131822596|lt=Tōnokubi Site|1=Tōnokubi Site}} | name_kanji ={{nihongo2|塔の首遺跡}} | name_small =Tōnokubi iseki | name_simple = Tōnokubi Site | municipality ={{ill|Tsushima, Nagasaki|en|Tsushima, Nagasaki|qid=Q991032|lt=Tsushima|1=Tsushima, Nagasaki}} | comments = Yayoi period graves<ref>{{cite web |url=http://www.museum.kyushu-u.ac.jp/WAJINDEN2004/02-3.html |script-title=ja:塔の首遺跡 |trans-title=Tōnokubi Site |language=Japanese |publisher=Kyushu University Museum |accessdate=14 June 2012 |url-status=dead |archiveurl=https://archive.today/20121219080600/http://www.museum.kyushu-u.ac.jp/WAJINDEN2004/02-3.html |archivedate=19 December 2012 }}</ref> | image = | lat =34.65988469 | lon =129.47032576 | type = 1 | id = 2777 }} |- {{NHS Japan row | name ={{ill|Hinoe Castle|en|Hinoe Castle|qid=Q1026929|lt=Hinoe Castle|1=Hinoe Castle}} ruins | name_kanji ={{nihongo2|日野江城跡}} | name_small =Hinoe-jō ato | name_simple = Hinoe Castle ruins | municipality =[[:en:Minamishimabara, Nagasaki|Minamishimabara]] | comments = Sengoku period castle ruins, one of the sites of the early Edo Period [[:en:Shimabara rebellion|Shimabara rebellion]] | image = 日野江城3.JPG | lat =32.65958475 | lon =130.25299628 | type = 2 | id = 2783 }} |- {{NHS Japan row | name =[[Hasami ware#Hizen Hasami Pottery Kiln Sites|Hizen Hasami Pottery Kiln Sites]] | name_kanji ={{nihongo2|肥前波佐見陶磁器窯跡}} | name_small = Hizen Hasami tōjiki kama ato | name_simple = Hizen Hasami Pottery Kiln Sites | municipality ={{ill|Hasami, Nagasaki|en|Hasami, Nagasaki|qid=Q1351244|lt=Hasami|1=Hasami, Nagasaki}} | comments = Edo Period pottery kiln ruins | image = Nakaogo, Hasami 01.jpg | lat =33.14918457 | lon =129.8698453 | type = 6 | id = 3265 }} |- {{NHS Japan row | name ={{ill|Hirado Dutch Trading Post|en|Hirado Dutch Trading Post|qid=Q126902601|lt=Hirado Dutch Trading Post|1=Hirado Dutch Trading Post}} | name_kanji ={{nihongo2|平戸和蘭商館跡}} | name_small=Hirado Oranda shōkan ato | name_simple = Hirado Dutch Trading Post | municipality ={{ill|Hirado, Nagasaki|en|Hirado, Nagasaki|qid=Q328601|lt=Hirado|1=Hirado, Nagasaki}} | comments = Edo Period Netherlands East Indies trading settlement | image = Hirado Dutch Trading Post 01.jpg | lat =33.37274627 | lon =129.55697795 | type =9 | id = 2738 }} |- {{NHS Japan row | name =[[Yatateyama Kofun Cluster]] | name_kanji ={{nihongo2|矢立山古墳群}} | name_small=Yatateyama kofun-gun | name_simple = Yatateyama Kofun Cluster | municipality ={{ill|Tsushima, Nagasaki|en|Tsushima, Nagasaki|qid=Q991032|lt=Tsushima|1=Tsushima, Nagasaki}} | comments = Kofun period tumuli cluster | image = | lat =34.23200094 | lon =129.2021064 | type =1 | id = 2775 }} |- |}
